<!doctype html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#16233a;text-align:center;padding:25px}.brand{color:#1b5ebd;font-size:11px;font-weight:bold}.event{font-size:19px;font-weight:bold;margin:10px}.number{background:#d5e7ff;border:1px solid #4a88dd;border-radius:10px;padding:18px;font-size:45px;font-weight:bold;color:#174f9f}.ref{font-family:monospace;font-size:9px;color:#5c76a0;margin:8px}.row{width:100%;margin:18px 0}.box{display:inline-block;width:43%;background:#f4f6f9;border-radius:8px;padding:10px;font-size:10px}.box strong{display:block;font-size:12px;margin-top:4px}.footer{font-size:10px;color:#65758c;margin-top:24px}</style></head><body><div class="brand">SIOLA Q · TIKET EVENT</div><div class="event">{{ $event->name }}</div><div class="number">{{ $participant->ticket_number }}</div><div class="ref">{{ $participant->reference_code }}</div><div class="row"><div class="box">Tanggal kedatangan<strong>{{ $event->arrival_date?->translatedFormat('d M Y') ?? $event->starts_at?->translatedFormat('d M Y') ?? '-' }}</strong></div><div class="box">Sesi<strong>{{ $event->session_label ?: ($event->starts_at ? $event->starts_at->format('H:i').' WIB' : '-') }}</strong></div></div><strong>{{ $participant->name }}</strong><div class="footer">Tunjukkan QR pada halaman tiket saat check-in di lokasi.</div></body></html>
